from functools import lru_cache
from google.cloud import pubsub_v1


def _project_id():
    return os.getenv("GOOGLE_CLOUD_PROJECT") or os.getenv("GCP_PROJECT") or os.getenv("GCLOUD_PROJECT")


def get_pubsub_publisher():
    return pubsub_v1.PublisherClient()


def get_pubsub_subscriber():
    return pubsub_v1.SubscriberClient()


def resolve_topic_path(project_id=None, topic_id=None):
    project = project_id or _project_id()
    topic = topic_id or os.getenv("PUBSUB_TOPIC_ID")
    if not project or not topic:
        raise ValueError("project_id and topic_id are required")
    return f"projects/{project}/topics/{topic}"


def resolve_subscription_path(project_id=None, subscription_id=None):
    project = project_id or _project_id()
    subscription = subscription_id or os.getenv("PUBSUB_SUBSCRIPTION_ID")
    if not project or not subscription:
        raise ValueError("project_id and subscription_id are required")
    return f"projects/{project}/subscriptions/{subscription}"


def resolve_dead_letter_topic_path(project_id=None, dead_letter_topic_id=None):
    project = project_id or _project_id()
    topic = dead_letter_topic_id or os.getenv("PUBSUB_DLQ_TOPIC_ID")
    if not project or not topic:
        raise ValueError("project_id and dead_letter_topic_id are required")
    return f"projects/{project}/topics/{topic}"
","messaging_models.py":"import base64
from datetime import datetime, timezone


def _now_iso():
    return datetime.now(timezone.utc).isoformat()


def build_event_payload(payload):
    if payload is None:
        return {"type": "event", "created_at": _now_iso()}
    if isinstance(payload, dict):
        normalized = dict(payload)
        normalized.setdefault("created_at", _now_iso())
        return normalized
    return {"type": "event", "created_at": _now_iso(), "payload": payload}


def build_dead_letter_payload(payload):
    if isinstance(payload, dict):
        normalized = dict(payload)
        normalized["dead_lettered_at"] = _now_iso()
        return normalized
    return {"payload": payload, "dead_lettered_at": _now_iso()}


def build_batch_messages(messages):
    if not isinstance(messages, list):
        raise ValueError("messages must be a list")
    batch = []
    for index, message in enumerate(messages):
        if isinstance(message, dict):
            payload = message.get("payload", message)
            msg_id = message.get("id", str(index))
            attributes = message.get("attributes", {})
        else:
            payload = message
            msg_id = str(index)
            attributes = {}
        batch.append({"id": str(msg_id), "payload": payload, "attributes": attributes})
    return batch


def normalize_attributes(attributes):
    if not attributes:
        return {}
    normalized = {}
    for key, value in dict(attributes).items():
        normalized[str(key)] = str(value)
    return normalized


def decode_pubsub_message(message):
    data = message.data or b""
    try:
        decoded = data.decode("utf-8")
    except Exception:
        decoded = base64.b64encode(data).decode("ascii")
    result = {"data": decoded, "message_id": getattr(message, "message_id", None), "attributes": dict(getattr(message, "attributes", {}) or {})}
    return result


def success_result(**kwargs):
    payload = dict(kwargs)
    payload.setdefault("status", "ok")
    payload.setdefault("processed_at", _now_iso())
    return payload
